// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Private_Bank} from "../src/Private_Bank.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Private_Bank c;

    function setUp() public {
        c = new Private_Bank(address(new Log()));
    }

    function _test(uint256 d1, uint256 d2) internal {
        d1 = bound(d1, 0, 1000000000000000000000000000000);
        d2 = bound(d2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= d1 + d2);
        vm.assume(d1 > c.MinDeposit() && d2 > c.MinDeposit());
        try c.Deposit{value: d1}() {} catch { return; }
        try c.Deposit{value: d2}() {} catch { return; }
        assertTrue(c.balances(address(this)) == d1 + d2);
    }

    function testFuzz_test(uint256 d1, uint256 d2) public {
        _test(d1, d2);
    }

    receive() external payable {}

    fallback() external payable {}
}
